// Adapted from idempotent-payments-lab src/services/refundService.ts:17-102 @ 7e9832b
// (Prisma replaced by an in-memory store; assertRefundAllowed from
// src/lib/domain/paymentStateMachine.ts:55-63 inlined; the fix shape finding L2 asks for
// — recompute the refunded sum inside a per-payment lock — applied so the module runs
// standalone).
export class RouteError extends Error {
  constructor(status, code, message) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

export function assertRefundAllowed(currentStatus, refundAmountMinor, remainingRefundableAmount) {
  if (currentStatus !== 'SUCCEEDED') {
    throw new RouteError(409, 'PAYMENT_NOT_REFUNDABLE', 'Only succeeded payments can be refunded.');
  }
  if (refundAmountMinor > remainingRefundableAmount) {
    throw new RouteError(409, 'REFUND_AMOUNT_EXCEEDS_CAPTURE', 'Refund amount exceeds the captured payment amount.');
  }
}

export class InMemoryPaymentStore {
  constructor(payment) {
    this.payment = { ...payment };
    this.refunds = [];
    this.locks = new Map();
  }
  async findPaymentById(id) {
    return this.payment.id === id ? { ...this.payment } : null;
  }
  async sumSuccessfulRefundsForPayment(paymentId) {
    return this.refunds
      .filter((refund) => refund.paymentId === paymentId && refund.status === 'SUCCEEDED')
      .reduce((sum, refund) => sum + refund.amountMinor, 0);
  }
  async createRefund(input) {
    const refund = { id: `ref-${this.refunds.length + 1}`, status: 'SUCCEEDED', ...input };
    this.refunds.push(refund);
    return { ...refund };
  }
  /** Serializes work per payment id, like SELECT ... FOR UPDATE on the payment row. */
  withPaymentLock(paymentId, work) {
    const previous = this.locks.get(paymentId) ?? Promise.resolve();
    const run = previous.catch(() => undefined).then(() => work());
    this.locks.set(paymentId, run.catch(() => undefined));
    return run;
  }
}

export function createRefundService(store) {
  return {
    async createRefundForPayment(input) {
      const payment = await store.findPaymentById(input.paymentId);

      if (!payment) {
        throw new RouteError(404, 'PAYMENT_NOT_FOUND', 'Payment not found.');
      }

      // Finding L2's fix: the refunded sum is recomputed INSIDE the payment lock. Two
      // concurrent refunds that both read the sum before either writes would both pass
      // the check, so read-and-assert must share the serialized region with the write.
      return store.withPaymentLock(payment.id, async () => {
        const refundedAmount = await store.sumSuccessfulRefundsForPayment(payment.id);
        const remainingRefundableAmount = payment.amountMinor - refundedAmount;
        assertRefundAllowed(payment.status, input.amountMinor, remainingRefundableAmount);

        const refund = await store.createRefund({
          paymentId: payment.id,
          amountMinor: input.amountMinor,
          reason: input.reason,
        });

        return { refundId: refund.id, paymentId: payment.id, refundStatus: refund.status };
      });
    },
  };
}

