// Adapted from idempotent-payments-lab src/services/providerSimulatorService.ts:157-186
// @ 7e9832b (deliverPendingWebhooks over an in-memory delivery store; the PENDING-only
// listing from src/repositories/webhookRepository.ts:29-37 replaced by an atomic claim —
// the missing claim/lock Trace D row D2 calls out — so the module runs standalone).
export class InMemoryDeliveryStore {
  constructor(deliveries) {
    this.deliveries = deliveries.map((delivery, index) => ({
      id: delivery.id ?? `del-${index + 1}`,
      status: 'PENDING',
      attempts: 0,
      ...delivery,
    }));
  }
  /** Atomically flips up to `limit` PENDING rows to DELIVERING and returns them (one UPDATE ... RETURNING). */
  async claimPendingWebhookDeliveries(limit) {
    const claimed = [];
    for (const delivery of this.deliveries) {
      if (claimed.length >= limit) break;
      if (delivery.status !== 'PENDING') continue;
      delivery.status = 'DELIVERING';
      claimed.push({ id: delivery.id, payload: delivery.payload });
    }
    return claimed;
  }
  /** Read-only PENDING listing (the shape the shipped repository exposes). */
  async listPendingWebhookDeliveries(limit) {
    return this.deliveries
      .filter((delivery) => delivery.status === 'PENDING')
      .slice(0, limit)
      .map((delivery) => ({ id: delivery.id, payload: delivery.payload }));
  }
  async markWebhookDeliveryDelivered(id) {
    const delivery = this.deliveries.find((row) => row.id === id);
    delivery.status = 'DELIVERED';
    delivery.attempts += 1;
  }
  async markWebhookDeliveryFailed(id, message) {
    const delivery = this.deliveries.find((row) => row.id === id);
    delivery.status = 'FAILED';
    delivery.attempts += 1;
    delivery.lastError = message;
  }
}

export async function deliverPendingWebhooks(store, processProviderWebhook, limit) {
  // Claiming (not just listing) is what makes a second concurrent dispatcher safe:
  // rows move out of PENDING in the same step that selects them.
  const deliveries = await store.claimPendingWebhookDeliveries(limit);
  const results = [];

  for (const delivery of deliveries) {
    try {
      await processProviderWebhook(delivery.payload);
      await store.markWebhookDeliveryDelivered(delivery.id);
      results.push({ id: delivery.id, status: 'DELIVERED', message: 'Webhook processed successfully.' });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown webhook failure';
      await store.markWebhookDeliveryFailed(delivery.id, message);
      results.push({ id: delivery.id, status: 'FAILED', message });
    }
  }

  return {
    delivered: results.filter((result) => result.status === 'DELIVERED').length,
    failed: results.filter((result) => result.status === 'FAILED').length,
    results,
  };
}

